DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_seasons_check' AND conrelid='seasons'::regclass) THEN ALTER TABLE "seasons" ADD CONSTRAINT "cdir_seasons_check" CHECK (("startsAt" < "endsAt")); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_seasons_check1' AND conrelid='seasons'::regclass) THEN ALTER TABLE "seasons" ADD CONSTRAINT "cdir_seasons_check1" CHECK (((NOT current) OR (status = 'OPEN'::text))); END IF; END $$;
