DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_player_seasons_status_check' AND conrelid='player_seasons'::regclass) THEN ALTER TABLE "player_seasons" ADD CONSTRAINT "cdir_player_seasons_status_check" CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_sessions_status_check' AND conrelid='sessions'::regclass) THEN ALTER TABLE "sessions" ADD CONSTRAINT "cdir_sessions_status_check" CHECK ((status = ANY (ARRAY['SCHEDULED'::text, 'CANCELLED'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_sessions_check' AND conrelid='sessions'::regclass) THEN ALTER TABLE "sessions" ADD CONSTRAINT "cdir_sessions_check" CHECK (("startsAt" < "endsAt")); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_sessions_venueId_tstzrange_excl' AND conrelid='sessions'::regclass) THEN ALTER TABLE "sessions" ADD CONSTRAINT "cdir_sessions_venueId_tstzrange_excl" EXCLUDE USING gist ("venueId" WITH =, tstzrange("startsAt", "endsAt", '[)'::text) WITH &&) WHERE ((status = 'SCHEDULED'::text)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_cross_trainings_check' AND conrelid='cross_trainings'::regclass) THEN ALTER TABLE "cross_trainings" ADD CONSTRAINT "cdir_cross_trainings_check" CHECK ((("sourceSessionId" IS NULL) OR ("sourceSessionId" <> "destinationSessionId"))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_attendance_status_check' AND conrelid='attendance'::regclass) THEN ALTER TABLE "attendance" ADD CONSTRAINT "cdir_attendance_status_check" CHECK ((status = ANY (ARRAY['PRESENT'::text, 'ABSENT'::text, 'EXCUSED'::text]))); END IF; END $$;
