DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_events_price_check' AND conrelid='events'::regclass) THEN ALTER TABLE "events" ADD CONSTRAINT "cdir_events_price_check" CHECK ((price >= (0)::numeric)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_events_status_check' AND conrelid='events'::regclass) THEN ALTER TABLE "events" ADD CONSTRAINT "cdir_events_status_check" CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'ARCHIVED'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_events_check' AND conrelid='events'::regclass) THEN ALTER TABLE "events" ADD CONSTRAINT "cdir_events_check" CHECK (("startsAt" < "endsAt")); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_events_check1' AND conrelid='events'::regclass) THEN ALTER TABLE "events" ADD CONSTRAINT "cdir_events_check1" CHECK (((NOT "registrationOpen") OR ((status = 'PUBLISHED'::text) AND ("formId" IS NOT NULL)))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_applications_status_check' AND conrelid='applications'::regclass) THEN ALTER TABLE "applications" ADD CONSTRAINT "cdir_applications_status_check" CHECK ((status = ANY (ARRAY['PENDING'::text, 'CONFIRMED'::text, 'REJECTED'::text]))); END IF; END $$;
