DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_invoices_status_check' AND conrelid='invoices'::regclass) THEN ALTER TABLE "invoices" ADD CONSTRAINT "cdir_invoices_status_check" CHECK ((status = ANY (ARRAY['PENDING'::text, 'PAID'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_invoices_check' AND conrelid='invoices'::regclass) THEN ALTER TABLE "invoices" ADD CONSTRAINT "cdir_invoices_check" CHECK (((status = 'PAID'::text) = ("paidAt" IS NOT NULL))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_contents_kind_check' AND conrelid='contents'::regclass) THEN ALTER TABLE "contents" ADD CONSTRAINT "cdir_contents_kind_check" CHECK ((kind = ANY (ARRAY['NEWS'::text, 'SPONSOR'::text, 'DOCUMENT'::text, 'PAGE'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_contents_status_check' AND conrelid='contents'::regclass) THEN ALTER TABLE "contents" ADD CONSTRAINT "cdir_contents_status_check" CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_members_role_check' AND conrelid='members'::regclass) THEN ALTER TABLE "members" ADD CONSTRAINT "cdir_members_role_check" CHECK ((role = ANY (ARRAY['ADMIN'::text, 'SECRETARY'::text, 'COORDINATOR'::text, 'COACH'::text, 'TREASURY'::text, 'EDITOR'::text, 'DIRECTOR'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_files_size_check' AND conrelid='files'::regclass) THEN ALTER TABLE "files" ADD CONSTRAINT "cdir_files_size_check" CHECK (((size >= 1) AND (size <= 5242880))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_user_profiles_avatarSource_check' AND conrelid='user_profiles'::regclass) THEN ALTER TABLE "user_profiles" ADD CONSTRAINT "cdir_user_profiles_avatarSource_check" CHECK (("avatarSource" = ANY (ARRAY['GOOGLE'::text, 'UPLOAD'::text, 'INITIALS'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_user_profiles_check' AND conrelid='user_profiles'::regclass) THEN ALTER TABLE "user_profiles" ADD CONSTRAINT "cdir_user_profiles_check" CHECK ((("avatarSource" <> 'UPLOAD'::text) OR (("avatarPath" IS NOT NULL) AND ("avatarVersion" IS NOT NULL)))); END IF; END $$;
