DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_matches_venue_check' AND conrelid='matches'::regclass) THEN ALTER TABLE "matches" ADD CONSTRAINT "cdir_matches_venue_check" CHECK ((venue = ANY (ARRAY['HOME'::text, 'AWAY'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_matches_status_check' AND conrelid='matches'::regclass) THEN ALTER TABLE "matches" ADD CONSTRAINT "cdir_matches_status_check" CHECK ((status = ANY (ARRAY['SCHEDULED'::text, 'FINAL'::text, 'CANCELLED'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_matches_check' AND conrelid='matches'::regclass) THEN ALTER TABLE "matches" ADD CONSTRAINT "cdir_matches_check" CHECK (("startsAt" < "endsAt")); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_matches_scoreFor_check' AND conrelid='matches'::regclass) THEN ALTER TABLE "matches" ADD CONSTRAINT "cdir_matches_scoreFor_check" CHECK ((("scoreFor" IS NULL) OR ("scoreFor" >= 0))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_matches_scoreAgainst_check' AND conrelid='matches'::regclass) THEN ALTER TABLE "matches" ADD CONSTRAINT "cdir_matches_scoreAgainst_check" CHECK ((("scoreAgainst" IS NULL) OR ("scoreAgainst" >= 0))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_player_requests_kind_check' AND conrelid='player_requests'::regclass) THEN ALTER TABLE "player_requests" ADD CONSTRAINT "cdir_player_requests_kind_check" CHECK ((kind = ANY (ARRAY['TRAINING'::text, 'MATCH'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_player_requests_quantity_check' AND conrelid='player_requests'::regclass) THEN ALTER TABLE "player_requests" ADD CONSTRAINT "cdir_player_requests_quantity_check" CHECK (((quantity >= 1) AND (quantity <= 20))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_player_requests_status_check' AND conrelid='player_requests'::regclass) THEN ALTER TABLE "player_requests" ADD CONSTRAINT "cdir_player_requests_status_check" CHECK ((status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text]))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='cdir_player_requests_check' AND conrelid='player_requests'::regclass) THEN ALTER TABLE "player_requests" ADD CONSTRAINT "cdir_player_requests_check" CHECK ((((kind = 'MATCH'::text) AND ("matchId" IS NOT NULL) AND (NOT recurring)) OR ((kind = 'TRAINING'::text) AND ("sessionId" IS NOT NULL)))); END IF; END $$;

CREATE INDEX IF NOT EXISTS matches_team_date ON matches("teamId","startsAt");
CREATE INDEX IF NOT EXISTS requests_status ON player_requests(status,"neededAt");
CREATE INDEX IF NOT EXISTS notifications_created ON notifications("createdAt");
CREATE UNIQUE INDEX IF NOT EXISTS one_head_coach ON coach_teams("teamId") WHERE function='HEAD';
CREATE UNIQUE INDEX IF NOT EXISTS one_assistant_coach ON coach_teams("teamId") WHERE function='ASSISTANT';
CREATE UNIQUE INDEX IF NOT EXISTS one_current_season ON seasons(current) WHERE current;
CREATE UNIQUE INDEX IF NOT EXISTS unique_active_application ON applications("eventId",lower(email),lower(name)) WHERE status<>'REJECTED';
CREATE UNIQUE INDEX IF NOT EXISTS member_email ON members(lower(email));
CREATE INDEX IF NOT EXISTS players_name ON players(lower(name));
CREATE INDEX IF NOT EXISTS sessions_team_date ON sessions("teamId","startsAt");
CREATE INDEX IF NOT EXISTS applications_review ON applications("seasonId",status);
CREATE INDEX IF NOT EXISTS events_visibility ON events(status,"startsAt");
CREATE INDEX IF NOT EXISTS audit_date ON audit_logs(at DESC);
CREATE OR REPLACE FUNCTION cdir_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END $$;
DROP TRIGGER IF EXISTS audit_append_only ON audit_logs;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION cdir_audit_immutable();
-- Forms referenced by an event keep their content and version; activation may change.
CREATE OR REPLACE FUNCTION cdir_form_version_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.name<>OLD.name OR NEW.version<>OLD.version OR NEW.fields<>OLD.fields) AND EXISTS(SELECT 1 FROM events WHERE "formId"=OLD.id) THEN RAISE EXCEPTION 'Create a new form version'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS form_version_guard ON forms;
CREATE TRIGGER form_version_guard BEFORE UPDATE ON forms FOR EACH ROW EXECUTE FUNCTION cdir_form_version_guard();
